#### Estimates

Next, we build a "spreadsheet-style" table to calculate the intermediate values needed for the final stratified variance and mean, summing the results at the bottom. We use `gt` to properly format the mathematical column headers.


::: {.cell}

```{.r .cell-code}
N <- sum(Nh)
pi_h <- Nh/N
weighted_ybar_h <- ybarh * pi_h
var_ybarh <- (1-nh/Nh)*sh^2/nh
var_h <- var_ybarh * pi_h^2

workingtable <- data.frame(
  Nh = Nh, 
  nh = nh,  
  ybarh = ybarh, 
  sh = sh, 
  s2h = sh^2, 
  pi_h = pi_h,
  weighted_ybar_h = weighted_ybar_h,
  var_ybarh = var_ybarh,
  var_h = var_h
)

workingtable <- rbind(workingtable, colSums(workingtable))
row.names(workingtable)[5] <- "Sum"
workingtable$Region <- rownames(workingtable)

workingtable |>
  gt(rowname_col = "Region") |>
  cols_label(
    Nh = md("$N_h$"),
    nh = md("$n_h$"),
    ybarh = md("$\\bar{y}_h$"),
    sh = md("$s_h$"),
    s2h = md("$s^2_h$"),
    pi_h = md("$\\pi_h = N_h/N$"),
    weighted_ybar_h = md("$\\bar{y}_h \\cdot \\pi_h$"),
