```{.r .cell-code}
## the ratio of estimated variance (Stratified SE / SRS SE)^2
ratio_var <- (str_mean_estimate_data(agstrat, "acres92", "region", "weight")["S.E."] / srs_mean_est(agsrs[, "acres92"], N=3078)["S.E."])^2
unname(ratio_var)
```

